1	use heck::{ToKebabCase, ToTitleCase};
2	use proc_macro2::TokenStream;
3	use quote::{ToTokens, quote};
4	use std::str::FromStr;
5	use syn::parse::{Parse, ParseStream};
6	use syn::token::Token;
7	use syn::{Attribute, Ident, Result, Token};
8	
9	/// Return an error at the given item.
10	macro_rules! bail {
11	    (callsite, $($tts:tt)*) => {
12	        return Err(syn::Error::new(
13	            proc_macro2::Span::call_site(),
14	            format!("typst: {}", format!($($tts)*))
15	        ))
16	    };
17	    ($item:expr, $($tts:tt)*) => {
18	        return Err(syn::Error::new_spanned(
19	            &$item,
20	            format!("typst: {}", format!($($tts)*))
21	        ))
22	    };
23	}
