25	/// Extract documentation comments from an attribute list.
26	pub fn documentation(attrs: &[syn::Attribute]) -> String {
27	    let mut doc = String::new();
28	
29	    // Parse doc comments.
30	    for attr in attrs {
31	        if let syn::Meta::NameValue(meta) = &attr.meta
32	            && meta.path.is_ident("doc")
33	        {
34	            if let syn::Expr::Lit(lit) = &meta.value
35	                && let syn::Lit::Str(string) = &lit.lit
36	            {
37	                let full = string.value();
38	                let line = full.strip_prefix(' ').unwrap_or(&full);
39	                doc.push_str(line);
40	                doc.push('\n');
41	            } else if let syn::Expr::Macro(expr) = &meta.value
42	                // The `stringify!` macro does not expand eagerly so we have
43	                // some very basic support for int and float expressions here.
44	                // This is e.g. used for paper sizes.
45	                && expr.mac.path.is_ident("stringify")
46	                && let Ok(lit) = syn::parse2::<syn::Lit>(expr.mac.tokens.clone())
47	                && let Some(value) = match &lit {
48	                syn::Lit::Int(int) => Some(int.base10_digits()),
49	                syn::Lit::Float(float) => Some(float.base10_digits()),
50	                _ => None,
51	            } {
52	                doc.push_str(value);
53	                doc.push('\n');
54	            }
55	        }
56	    }
57	
58	    doc.trim().into()
59	}
60	
61	/// Whether an attribute list has a specified attribute.
62	pub fn has_attr(attrs: &mut Vec<syn::Attribute>, target: &str) -> bool {
63	    take_attr(attrs, target).is_some()
64	}
65	
66	/// Whether an attribute list has a specified attribute.
67	pub fn parse_attr<T: Parse>(
68	    attrs: &mut Vec<syn::Attribute>,
69	    target: &str,
70	) -> Result<Option<Option<T>>> {
71	    take_attr(attrs, target)
72	        .map(|attr| {
73	            Ok(match attr.meta {
74	                syn::Meta::Path(_) => None,
75	                syn::Meta::List(list) => Some(list.parse_args()?),
76	                syn::Meta::NameValue(meta) => bail!(meta, "not valid here"),
77	            })
78	        })
79	        .transpose()
80	}
81	
82	/// Whether an attribute list has a specified attribute.
83	pub fn take_attr(
84	    attrs: &mut Vec<syn::Attribute>,
85	    target: &str,
86	) -> Option<syn::Attribute> {
87	    attrs
88	        .iter()
89	        .position(|attr| attr.path().is_ident(target))
90	        .map(|i| attrs.remove(i))
91	}
92	
93	/// Ensure that no unrecognized attributes remain.
94	pub fn validate_attrs(attrs: &[syn::Attribute]) -> Result<()> {
95	    for attr in attrs {
96	        if !attr.path().is_ident("doc") && !attr.path().is_ident("derive") {
97	            let ident = attr.path().get_ident().unwrap();
98	            bail!(ident, "unrecognized attribute: {ident}");
99	        }
100	    }
101	    Ok(())
102	}
103	
104	/// Quotes an option literally.
105	pub fn quote_option<T: ToTokens>(option: &Option<T>) -> TokenStream {
106	    if let Some(value) = option {
107	        quote! { Some(#value) }
108	    } else {
109	        quote! { None }
110	    }
111	}
112	
113	/// Parse a metadata key-value pair, separated by `=`.
114	pub fn parse_key_value<K: Token + Default + Parse, V: Parse>(
115	    input: ParseStream,
116	) -> Result<Option<V>> {
117	    if !input.peek(|_| K::default()) {
118	        return Ok(None);
119	    }
120	
121	    let _: K = input.parse()?;
122	    let _: Token![=] = input.parse()?;
123	    let value: V = input.parse::<V>()?;
124	    eat_comma(input);
125	    Ok(Some(value))
126	}
127	
128	/// Parse a metadata key-array pair, separated by `=`.
129	pub fn parse_key_value_array<K: Token + Default + Parse, V: Parse>(
130	    input: ParseStream,
131	) -> Result<Vec<V>> {
132	    Ok(parse_key_value::<K, Array<V>>(input)?.map_or(vec![], |array| array.0))
133	}
134	
135	/// Parse a metadata key-string pair, separated by `=`.
136	pub fn parse_string<K: Token + Default + Parse>(
137	    input: ParseStream,
138	) -> Result<Option<String>> {
139	    Ok(parse_key_value::<K, syn::LitStr>(input)?.map(|s| s.value()))
140	}
141	
142	/// Parse a metadata key-string pair, separated by `=`.
143	pub fn parse_string_array<K: Token + Default + Parse>(
144	    input: ParseStream,
145	) -> Result<Vec<String>> {
146	    Ok(parse_key_value_array::<K, syn::LitStr>(input)?
147	        .into_iter()
148	        .map(|lit| lit.value())
149	        .collect())
150	}
151	
152	/// Parse a metadata flag that can be present or not.
153	pub fn parse_flag<K: Token + Default + Parse>(input: ParseStream) -> Result<bool> {
154	    if input.peek(|_| K::default()) {
155	        let _: K = input.parse()?;
156	        eat_comma(input);
157	        return Ok(true);
158	    }
159	    Ok(false)
160	}
161	
162	/// Parse a comma if there is one.
163	pub fn eat_comma(input: ParseStream) {
164	    if input.peek(Token![,]) {
165	        let _: Token![,] = input.parse().unwrap();
166	    }
167	}
168	
169	/// Determine the normal and title case name of a function, type, or element.
170	pub fn determine_name_and_title(
171	    specified_name: Option<String>,
172	    specified_title: Option<String>,
173	    ident: &syn::Ident,
174	    trim: Option<fn(&str) -> &str>,
175	) -> Result<(String, String)> {
176	    let name = {
177	        let trim = trim.unwrap_or(|s| s);
178	        let default = trim(&ident.to_string()).to_kebab_case();
179	        if specified_name.as_ref() == Some(&default) {
180	            bail!(ident, "name was specified unnecessarily");
181	        }
182	        specified_name.unwrap_or(default)
183	    };
184	
185	    let title = {
186	        let default = name.to_title_case();
187	        if specified_title.as_ref() == Some(&default) {
188	            bail!(ident, "title was specified unnecessarily");
189	        }
190	        specified_title.unwrap_or(default)
191	    };
192	
193	    Ok((name, title))
194	}
195	
196	/// A generic parseable array.
197	struct Array<T>(Vec<T>);
198	
199	impl<T: Parse> Parse for Array<T> {
200	    fn parse(input: ParseStream) -> Result<Self> {
201	        let content;
202	        syn::bracketed!(content in input);
203	
204	        let mut elems = Vec::new();
205	        while !content.is_empty() {
206	            let first: T = content.parse()?;
207	            elems.push(first);
208	            if !content.is_empty() {
209	                let _: Token![,] = content.parse()?;
210	            }
211	        }
212	
213	        Ok(Self(elems))
214	    }
215	}
216	
217	/// Shorthand for `::typst_library::foundations`.
218	#[expect(non_camel_case_types)]
219	pub struct foundations;
220	
221	impl quote::ToTokens for foundations {
222	    fn to_tokens(&self, tokens: &mut TokenStream) {
223	        quote! { ::typst_library::foundations }.to_tokens(tokens);
224	    }
225	}
226	
227	/// For parsing attributes of the form:
228	/// ```ignore
229	/// #[attr(
230	///   statement;
231	///   statement;
232	///   returned_expression
233	/// )]
234	/// ```
235	pub struct BlockWithReturn {
236	    pub prefix: Vec<syn::Stmt>,
237	    pub expr: syn::Stmt,
238	}
239	
240	impl Parse for BlockWithReturn {
241	    fn parse(input: ParseStream) -> Result<Self> {
242	        let mut stmts = syn::Block::parse_within(input)?;
243	        let Some(expr) = stmts.pop() else {
244	            return Err(input.error("expected at least one expression"));
245	        };
246	        Ok(Self { prefix: stmts, expr })
247	    }
248	}
249	
250	/// Parse a bare `type Name;` item.
251	#[expect(dead_code)]
252	pub struct BareType {
253	    pub attrs: Vec<Attribute>,
254	    pub type_token: Token![type],
255	    pub ident: Ident,
256	    pub semi_token: Token![;],
257	}
258	
259	impl Parse for BareType {
260	    fn parse(input: ParseStream) -> Result<Self> {
261	        Ok(Self {
262	            attrs: input.call(Attribute::parse_outer)?,
263	            type_token: input.parse()?,
264	            ident: input.parse()?,
265	            semi_token: input.parse()?,
266	        })
267	    }
268	}
269	
270	pub mod kw {
271	    syn::custom_keyword!(name);
272	    syn::custom_keyword!(span);
273	    syn::custom_keyword!(title);
274	    syn::custom_keyword!(since);
275	    syn::custom_keyword!(scope);
276	    syn::custom_keyword!(contextual);
277	    syn::custom_keyword!(cast);
278	    syn::custom_keyword!(constructor);
279	    syn::custom_keyword!(keywords);
280	    syn::custom_keyword!(parent);
281	    syn::custom_keyword!(ext);
282	}
283	
284	/// When a feature was introduced.
285	pub enum Since {
286	    /// The feature was introduced before Typst 0.1.0.
287	    Forever,
288	    /// The feature was introduced in a version released after Typst 0.1.0.
289	    Version([u32; 3]),
290	    /// The feature is not present in any official Typst release.
291	    Unreleased,
292	}
293	
294	impl Since {
295	    const FOREVER: &'static str = "forever";
296	    const UNRELEASED: &'static str = "unreleased";
297	}
298	
299	impl FromStr for Since {
300	    type Err = ();
301	
302	    fn from_str(s: &str) -> std::result::Result<Self, Self::Err> {
303	        if s == Self::FOREVER {
304	            Ok(Self::Forever)
305	        } else if s == Self::UNRELEASED {
306	            Ok(Self::Unreleased)
307	        } else if let Ok(&[major, minor, patch]) = s
308	            .splitn(3, '.')
309	            .map(u32::from_str)
310	            .collect::<std::result::Result<Vec<_>, _>>()
311	            .as_deref()
312	        {
313	            Ok(Self::Version([major, minor, patch]))
314	        } else {
315	            Err(())
316	        }
317	    }
318	}
319	
320	impl Parse for Since {
321	    fn parse(input: ParseStream) -> Result<Self> {
322	        let value = input.parse::<syn::LitStr>()?;
323	        let Ok(since) = value.value().parse() else {
324	            bail!(
325	                value,
326	                "invalid version; use `{:?}` for an unreleased version",
327	                Self::UNRELEASED,
328	            )
329	        };
330	        Ok(since)
331	    }
332	}
333	
334	impl ToTokens for Since {
335	    fn to_tokens(&self, tokens: &mut TokenStream) {
336	        match self {
337	            Self::Forever => quote! { #foundations::Since::Forever },
338	            Self::Version([major, minor, patch]) => {
339	                quote! { #foundations::Since::Version([#major, #minor, #patch]) }
340	            }
341	            Self::Unreleased => quote! { #foundations::Since::Unreleased },
342	        }
343	        .to_tokens(tokens);
344	    }
345	}
346	
347	/// Extract the first line of documentation.
348	pub fn oneliner(docs: &str) -> String {
349	    let paragraph = docs.split("\n\n").next().unwrap_or_default();
350	    let mut depth = 0;
351	    let mut period = false;
352	    let mut end = paragraph.len();
353	    for (i, c) in paragraph.char_indices() {
354	        match c {
355	            '(' | '[' | '{' => depth += 1,
356	            ')' | ']' | '}' => depth -= 1,
357	            '.' if depth == 0 => period = true,
358	            c if period && c.is_whitespace() && !docs[..i].ends_with("e.g.") => {
359	                end = i;
360	                break;
361	            }
362	            _ => period = false,
363	        }
364	    }
365	    String::from(&docs[..end]).replace("\r\n", " ").replace("\n", " ")
366	}
